From c3e4baa63fb2de7ec1c4c3e719f8aa9c23836da2 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:41:00 +0100
Subject: [PATCH] applet, kcm: say when a connection fails because the adapter
 is off

With more than one adapter, connecting to a device paired to an adapter
that is turned off only showed a generic "Connection to the device
failed" or "Input/output error". Name the turned off adapter instead.

BUG: 506264
---
 src/applet/devicesstateproxymodel.cpp  |  6 +++++-
 src/kcm/ui/Device.qml                  |  2 +-
 src/kcm/ui/DeviceConnectionSidebar.qml |  2 +-
 src/kcm/ui/main.qml                    | 10 +++++-----
 4 files changed, 12 insertions(+), 8 deletions(-)

diff --git a/src/applet/devicesstateproxymodel.cpp b/src/applet/devicesstateproxymodel.cpp
index e00ffab6..82a1497e 100644
--- a/src/applet/devicesstateproxymodel.cpp
+++ b/src/applet/devicesstateproxymodel.cpp
@@ -286,7 +286,11 @@ void DevicesStateProxyModel::notifyIfConnectionFailed(const BluezQt::PendingCall
     const auto address = index.data(BluezQt::DevicesModel::AddressRole).toString();

     const auto title = i18nc("@label %1 is the name of a Bluetooth device", "Could not connect to device “%1”", name);
-    const auto text = errorText(call);
+    const auto text = index.data(BluezQt::DevicesModel::AdapterPoweredRole).toBool()
+        ? errorText(call)
+        : i18nc("Notification when the connection failed because the adapter is off, %1 is the name of a Bluetooth adapter",
+                "The Bluetooth adapter “%1” is turned off",
+                index.data(BluezQt::DevicesModel::AdapterNameRole).toString());

     KNotification *notification = new KNotification(QStringLiteral("ConnectionFailed"), KNotification::CloseOnTimeout, this);
     notification->setComponentName(QStringLiteral("bluedevil"));
diff --git a/src/kcm/ui/Device.qml b/src/kcm/ui/Device.qml
index 85814855..9f431cb5 100644
--- a/src/kcm/ui/Device.qml
+++ b/src/kcm/ui/Device.qml
@@ -87,7 +87,7 @@ KCMUtils.SimpleKCM {
         call.finished.connect(call => {
             indicator.running = false
             if (call.error) {
-                errorMessage.text = call.errorText
+                errorMessage.text = root.device.adapter.powered ? call.errorText : i18nc("@info %1 is the name of a Bluetooth adapter", "The Bluetooth adapter “%1” is turned off", root.device.adapter.name)
                 errorMessage.visible = true
             }
         })
diff --git a/src/kcm/ui/DeviceConnectionSidebar.qml b/src/kcm/ui/DeviceConnectionSidebar.qml
index c9603132..a1780bd5 100644
--- a/src/kcm/ui/DeviceConnectionSidebar.qml
+++ b/src/kcm/ui/DeviceConnectionSidebar.qml
@@ -31,7 +31,7 @@ Bigscreen.SidebarOverlay {
             connecting = false
             disconnecting = false
             if (call.error) {
-                errorMessage.text = call.errorText
+                errorMessage.text = device.adapter.powered ? call.errorText : i18nc("@info %1 is the name of a Bluetooth adapter", "The Bluetooth adapter “%1” is turned off", device.adapter.name)
                 errorMessage.visible = true
             }
         })
diff --git a/src/kcm/ui/main.qml b/src/kcm/ui/main.qml
index 5d0da102..b29450d9 100644
--- a/src/kcm/ui/main.qml
+++ b/src/kcm/ui/main.qml
@@ -59,12 +59,12 @@ KCMUtils.ScrollViewKCM {
         }
     ]

-    function makeCall(call: BluezQt.PendingCall): void {
+    function makeCall(call: BluezQt.PendingCall, device: BluezQt.Device): void {
         busyIndicator.running = true
         call.finished.connect(call => {
             busyIndicator.running = false
             if (call.error) {
-                errorMessage.text = call.errorText
+                errorMessage.text = !device || device.adapter.powered ? call.errorText : i18nc("@info %1 is the name of a Bluetooth adapter", "The Bluetooth adapter “%1” is turned off", device.adapter.name)
                 errorMessage.visible = true
             }
         })
@@ -85,7 +85,7 @@ KCMUtils.ScrollViewKCM {
         parent: root.QQC2.Overlay.overlay

         onCall: call => {
-            root.makeCall(call);
+            root.makeCall(call, null);
         }
     }

@@ -207,9 +207,9 @@ KCMUtils.ScrollViewKCM {

                         onTriggered: {
                             if (delegate.model.Connected) {
-                                root.makeCall(delegate.model.Device.disconnectFromDevice())
+                                root.makeCall(delegate.model.Device.disconnectFromDevice(), delegate.model.Device)
                             } else {
-                                root.makeCall(delegate.model.Device.connectToDevice())
+                                root.makeCall(delegate.model.Device.connectToDevice(), delegate.model.Device)
                             }
                         }
                     },
-- 
